14	// 两者可以、而且在本场景中必然使用不同的时刻：查询结果只是只读的版本视图，
15	// 不能成为随后报价的时间依据。因此——
16	//
17	//   - 在过去时刻查到旧版仍有效，不代表稍后（旧版已被替代后）受理的报价
18	//     还能按旧版确认；报价只认首次受理时刻。
19	//   - 对未来时刻的查询失败（该时刻无生效版本）不改变账本时钟，也不留下
20	//     任何状态；回到原来的受理时刻引用当时有效的新版，仍应正常确认。
21	//
22	// 本组测试只走现有的公开入口（EffectiveVersionAt / Quote / Lookup），
23	// 不新增入口，也不改变拒绝的含义（version_expired、ErrNoEffectiveVersion 等）。
24	//
25	// 固定时间线（均为 UTC，结束时刻不含）：
26	//
27	//	旧版 seat-v1：单价 150 分，2026-03-01 00:00 起，登记结束 2026-03-31 00:00
28	//	新版 seat-v2：单价 180 分，2026-03-10 00:00 起替代旧版，2026-03-20 00:00 结束
29	//	查询时刻一：2026-03-09 00:00（旧版实际有效，登记结束尚未到）
30	//	报价首次受理时刻：2026-03-15 10:00（旧版实际有效期已止于 3 月 10 日）
31	//	查询时刻二：2026-03-20 00:00（新版结束时刻，不含；两版都不生效）
32	var (
33		qqV1Start     = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
34		qqV1RegEnd    = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)  // 旧版登记结束（不含）
35		qqV2Start     = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)  // 新版替代旧版的交接点
36		qqV2End       = time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC)  // 新版结束（不含）
37		qqPastQuery   = time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC)   // 查询时刻一：过去
38		qqAcceptAt    = time.Date(2026, 3, 15, 10, 0, 0, 0, time.UTC) // 报价首次受理时刻
39		qqFutureQuery = qqV2End                                       // 查询时刻二：未来的结束点
40	)
41	
42	// newQueryQuoteBook 返回一本已登记上述旧版/新版交接关系的账本，
43	// 账本时钟固定在报价首次受理时刻 2026-03-15 10:00。
44	func newQueryQuoteBook(t *testing.T, start time.Time) (*Book, func(time.Time)) {
45		t.Helper()
46		now, setNow := fixedClock(start)
47		b := NewBook(WithClock(now))
48		oldEnd := qqV1RegEnd
49		if err := b.RegisterVersion(RegisterRequest{
50			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
51			Start: qqV1Start, End: &oldEnd,
52		}); err != nil {
53			t.Fatalf("register seat-v1: %v", err)
54		}
55		newEnd := qqV2End
56		if err := b.RegisterVersion(RegisterRequest{
57			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
58			Start: qqV2Start, End: &newEnd, Replaces: "seat-v1",
59		}); err != nil {
60			t.Fatalf("register seat-v2: %v", err)
61		}
62		return b, setNow
63	}
64	
65	// TestEffectiveQueryDoesNotSetQuoteAcceptanceTime 围绕同一费率项走一遍完整
66	// 使用过程：先在过去时刻查到旧版，再在更晚的受理时刻引用旧版（应拒绝）；
67	// 再对未来的“无生效版本”时刻查询失败后，回到原受理时刻引用新版（应确认）。
68	// 两次报价的首次受理时刻都必须是 3 月 15 日 10:00，与各自之前的查询时刻无关。
69	func TestEffectiveQueryDoesNotSetQuoteAcceptanceTime(t *testing.T) {
70		// 账本时钟自始至终固定在报价受理时刻 3 月 15 日 10:00，全程不推进。
71		b, setNow := newQueryQuoteBook(t, qqAcceptAt)
72	
73		// ① 查询 3 月 9 日：当时生效的是旧版 seat-v1。
74		old, err := b.EffectiveVersionAt("seat", qqPastQuery)
75		if err != nil {
76			t.Fatalf("3 月 9 日应查到生效的旧版: %v", err)
77		}
78		if old.ItemID != "seat" || old.VersionID != "seat-v1" || old.UnitPrice != 150 {
79			t.Fatalf("3 月 9 日选错版本: %+v", old)
80		}
81		// 同一份视图必须能区分“登记结束”和“实际结束”：
82		// 登记结束仍是 3 月 31 日（尚未到），但旧版已被新版替代，
83		// 实际有效区间止于交接点 3 月 10 日。
84		if old.End == nil || !old.End.Equal(qqV1RegEnd) {
85			t.Fatalf("旧版登记结束应为 3 月 31 日: %v", old.End)
86		}
87		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(qqV2Start) {
88			t.Fatalf("旧版实际结束应为交接点 3 月 10 日: %v", old.EffectiveEnd)
89		}
90		if old.End.Equal(*old.EffectiveEnd) {
91			t.Fatal("登记结束与实际结束必须是两个不同的边界，不能混为同一个值")
92		}
93		if old.SupersededBy != "seat-v2" {
94			t.Fatalf("旧版应显示由 seat-v2 替代: %q", old.SupersededBy)
95		}
96	
97		// ② 用从未使用过的请求标识引用旧版报价，数量 4。
98		//    受理时刻仍是账本时钟 3 月 15 日 10:00，而不是上面查询所用的 3 月 9 日：
99		//    查询结果不能成为报价的时间依据。旧版实际止于 3 月 10 日，受理时已到期。
100		setNow(qqAcceptAt) // 显式确认时钟仍在原受理时刻，未被查询带动。
101		rejectedReq := QuoteRequest{
102			RequestID: "qq-old-version-after-query",
103			ItemID:    "seat",
104			VersionID: "seat-v1",
105			Quantity:  4,
106		}
107		rejected, err := b.Quote(rejectedReq)
108		if err != nil {
109			t.Fatalf("引用已失效版本是正常受理后拒绝，调用错误应为空, got %v", err)
110		}
111		if rejected.Confirmed {
112			t.Fatalf("旧版在 3 月 15 日已失效，不能确认，更不能按 3 月 9 日的查询结果计价: %+v", rejected)
113		}
114		if rejected.Reason != ReasonVersionExpired {
115			t.Fatalf("拒绝原因应为 version_expired, got %q", rejected.Reason)
116		}
117		// 拒绝结果单价和总价均为零——零金额不代表登记单价为零。
118		if rejected.UnitPrice != 0 || rejected.Total != 0 {
119			t.Fatalf("拒绝结果单价/总价应为零: 单价=%d 总价=%d", rejected.UnitPrice, rejected.Total)
120		}
121		// 结果保留提交的费率项、旧版标识和数量，不能自动改用新版确认。
122		if rejected.Request != rejectedReq {
123			t.Fatalf("拒绝结果必须原样保留请求（费率项/旧版标识/数量）: %+v vs %+v",
124				rejected.Request, rejectedReq)
125		}
126		if rejected.Request.VersionID == "seat-v2" {
127			t.Fatalf("引用旧版不能被自动改成新版: %+v", rejected.Request)
128		}
129		// 首次受理时刻必须是 3 月 15 日 10:00，绝不能写成查询时刻 3 月 9 日。
130		if !rejected.AcceptedAt.Equal(qqAcceptAt) {
131			t.Fatalf("首次受理时刻应为 3 月 15 日 10:00, got %v", rejected.AcceptedAt)
132		}
133		if rejected.AcceptedAt.Equal(qqPastQuery) {
134			t.Fatalf("受理时刻被错误地写成了查询时刻 3 月 9 日: %v", rejected.AcceptedAt)
135		}
136	
137		// ③ 再查询未来的 3 月 20 日零点（新版结束时刻，不含）：
138		//    此时没有任何生效版本，旧版不会因为新版到期而重新生效。
139		if _, err := b.EffectiveVersionAt("seat", qqFutureQuery); !errors.Is(err, ErrNoEffectiveVersion) {
140			t.Fatalf("3 月 20 日零点应返回 ErrNoEffectiveVersion, got %v", err)
141		}
142	
143		// ④ 未来时刻的查询失败之后，受理时刻仍是原来的 3 月 15 日 10:00。
144		//    换用另一个从未使用过的标识引用新版：新版在受理时刻有效，确认 180×4=720。
145		setNow(qqAcceptAt)
146		confirmedReq := QuoteRequest{
147			RequestID: "qq-new-version-after-future-query",
148			ItemID:    "seat",
149			VersionID: "seat-v2",
150			Quantity:  4,
151		}
152		confirmed, err := b.Quote(confirmedReq)
153		if err != nil {
154			t.Fatalf("引用受理时刻有效的新版应正常受理，调用错误应为空, got %v", err)
155		}
156		if !confirmed.Confirmed {
157			t.Fatalf("新版在 3 月 15 日有效，应确认，未来查询失败不能污染本次报价: %+v", confirmed)
158		}
159		if confirmed.UnitPrice != 180 || confirmed.Total != 720 {
160			t.Fatalf("应按新版 180 分确认总价 720 分: 单价=%d 总价=%d",
161				confirmed.UnitPrice, confirmed.Total)
162		}
163		if confirmed.Reason != ReasonNone {
164			t.Fatalf("确认结果拒绝原因为空, got %q", confirmed.Reason)
165		}
166		// 来源是调用方指定的新版。
167		if confirmed.Request != confirmedReq || confirmed.Request.VersionID != "seat-v2" {
168			t.Fatalf("确认结果必须保留新版来源: %+v vs %+v", confirmed.Request, confirmedReq)
169		}
170		// 受理时刻仍是 3 月 15 日 10:00，不能写成未来查询时刻 3 月 20 日。
171		if !confirmed.AcceptedAt.Equal(qqAcceptAt) {
172			t.Fatalf("首次受理时刻应为 3 月 15 日 10:00, got %v", confirmed.AcceptedAt)
173		}
174		if confirmed.AcceptedAt.Equal(qqFutureQuery) {
175			t.Fatalf("受理时刻被错误地写成了未来查询时刻 3 月 20 日: %v", confirmed.AcceptedAt)
176		}
177	
178		// ⑤ 两笔报价都应能按各自标识查到，且与首次返回的结果逐条一致。
179		gotRejected, err := b.Lookup(rejectedReq.RequestID)
180		if err != nil {
181			t.Fatalf("被拒绝的首次结果也应可查: %v", err)
182		}
183		if gotRejected != rejected {
184			t.Fatalf("拒绝结果 Lookup 与首次返回不一致: %+v vs %+v", gotRejected, rejected)
185		}
186		gotConfirmed, err := b.Lookup(confirmedReq.RequestID)
187		if err != nil {
188			t.Fatalf("已确认的首次结果应可查: %v", err)
189		}
190		if gotConfirmed != confirmed {
191			t.Fatalf("确认结果 Lookup 与首次返回不一致: %+v vs %+v", gotConfirmed, confirmed)
192		}
193	
194		// 原样重试（相同标识、相同内容）同样返回各自的首次结果，不按当前账本重算。
195		replayRejected, err := b.Quote(rejectedReq)
196		if err != nil || replayRejected != rejected {
197			t.Fatalf("拒绝结果原样重试应返回首次结果: %+v (%v), first %+v",
198				replayRejected, err, rejected)
199		}
200		replayConfirmed, err := b.Quote(confirmedReq)
201		if err != nil || replayConfirmed != confirmed {
202			t.Fatalf("确认结果原样重试应返回首次结果: %+v (%v), first %+v",
203				replayConfirmed, err, confirmed)
204		}
205	}
206	
207	// TestQuoteAcceptanceTimeUnaffectedByQueries 从另一个角度锁定同一约定：
208	// 在相同的受理时刻，无论此前对多少个不同时刻（过去命中、未来落空）做过
209	// 查询，报价结论都必须与“完全不查询直接报价”一致——查询不推进账本时钟，
210	// 也不留下任何能影响 Quote 的时间状态。
211	func TestQuoteAcceptanceTimeUnaffectedByQueries(t *testing.T) {
212		// 账本 A：注册后不做任何查询，直接在受理时刻报价。
213		bookA, _ := newQueryQuoteBook(t, qqAcceptAt)
214	
215		// 账本 B：注册后先对一串时刻反复查询（含成功与失败），再报同样的请求。
216		bookB, setNowB := newQueryQuoteBook(t, qqAcceptAt)
217		queryTimes := []time.Time{
218			qqPastQuery,   // 过去：命中旧版
219			qqV2Start,     // 交接点：命中新版
220			qqAcceptAt,    // 受理时刻本身：命中新版
221			qqFutureQuery, // 未来结束点：无生效版本
222			time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC), // 更远的未来：无生效版本
223			qqPastQuery,   // 再回到过去重复查询
224			qqFutureQuery, // 再重复一次失败查询
225		}
226		for i, at := range queryTimes {
227			_, _ = bookB.EffectiveVersionAt("seat", at) // 结论如何都不应影响后面的报价
228			// 显式把时钟拨回受理时刻，证明报价只依赖这个时钟而非任何查询参数。
229			setNowB(qqAcceptAt)
230			_ = i
231		}
232	
233		// 两本账用完全相同的请求（含相同标识）引用新版，结果必须逐条相等。
234		newReq := QuoteRequest{
235			RequestID: "qqcmp-new-version", ItemID: "seat", VersionID: "seat-v2", Quantity: 4,
236		}
237		outA, errA := bookA.Quote(newReq)
238		outB, errB := bookB.Quote(newReq)
239		if errA != nil || errB != nil {
240			t.Fatalf("两本账引用新版都不应返回调用错误: %v %v", errA, errB)
241		}
242		if outA != outB {
243			t.Fatalf("查询不应改变报价结果: 无查询=%+v 多次查询=%+v", outA, outB)
244		}
245		if !outB.Confirmed || outB.UnitPrice != 180 || outB.Total != 720 ||
246			outB.Reason != ReasonNone || !outB.AcceptedAt.Equal(qqAcceptAt) {
247			t.Fatalf("受理时刻引用新版应确认 720 分且受理时刻为 3 月 15 日 10:00: %+v", outB)
248		}
249	
250		// 同样的请求引用旧版：两本账都应按受理时刻判定 version_expired，金额为零，
251		// 而不会因为账本 B 查过 3 月 9 日（旧版当时有效）就改成确认。
252		oldReq := QuoteRequest{
253			RequestID: "qqcmp-old-version", ItemID: "seat", VersionID: "seat-v1", Quantity: 4,
254		}
255		oldA, errA := bookA.Quote(oldReq)
256		oldB, errB := bookB.Quote(oldReq)
257		if errA != nil || errB != nil {
258			t.Fatalf("两本账引用旧版都不应返回调用错误: %v %v", errA, errB)
259		}
260		if oldA != oldB {
261			t.Fatalf("查询不应改变旧版报价的拒绝结果: 无查询=%+v 多次查询=%+v", oldA, oldB)
262		}
263		if oldB.Confirmed || oldB.Reason != ReasonVersionExpired ||
264			oldB.UnitPrice != 0 || oldB.Total != 0 ||
265			!oldB.AcceptedAt.Equal(qqAcceptAt) || oldB.Request != oldReq {
266			t.Fatalf("受理时刻引用旧版应为 version_expired 拒绝、金额为零并保留原请求: %+v", oldB)
267		}
268	}
269

